export function TerminalSplitView({
  layout,
  sessions,
  onActivateTab = () => undefined,
  onCloseTab = () => undefined,
  onCloseOtherTabs,
  onCloseTabsToRight,
  onCloseTabsToLeft,
  onReorderTab,
  onMoveTabToGroup,
  onMoveTabToSplit,
  onDetachPaneToTab,
  onRenameTab,
  onToggleTabPin,
